src='''def transform(g):
    from collections import Counter, deque
    h=len(g); w=len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    out=[row[:] for row in g]
    seen=set()
    for i in range(h):
        for j in range(w):
            c=g[i][j]
            if c==bg or (i,j) in seen:
                continue
            q=deque([(i,j)]); seen.add((i,j)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for a,b in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==c:
                        seen.add((a,b)); q.append((a,b))
            if len(cells)>=4:
                y0=min(y for y,x in cells); y1=max(y for y,x in cells)
                x0=min(x for y,x in cells); x1=max(x for y,x in cells)
                for y in range(y0,y1+1):
                    for x in range(x0,x1+1): out[y][x]=c
            else:
                for y,x in cells: out[y][x]=bg
    return out
'''
